class_name CharacterStats extends Resource
@export var parts: Dictionary = {"head":20.0,"chest":40.0,"belly":30.0,"arm_l":18.0,"arm_r":18.0,"leg_l":22.0,"leg_r":22.0}
@export var needs: Dictionary = {"hydration":100.0,"food":100.0,"rest":100.0,"warm":0.0}
@export var tags: Array[StringName] = []   # «bleed:leg_l», «fracture:arm_r», «night_vision»

class_name SkillSet extends Resource
@export var practice: Dictionary = {"athletics":0.0,"stealth":0.0,"craft":0.0,"build":0.0,
                                    "medicine":0.0,"firearms":0.0,"melee":0.0,"motherland":0.0}
func rank(id: StringName) -> int:
    return clampi(int(practice.get(id, 0.0) / 20.0), 0, 4)
func add_practice(id: StringName, amount: float, action_key: StringName) -> void:
    practice[id] = clampf(practice.get(id, 0.0) + amount * PracticeTracker.repeat_mul(action_key), 0.0, 100.0)

class_name OriginDef extends Resource
@export var id: StringName            # &"medic" | &"engineer" | &"soldier" | &"builder"
@export var pillar: StringName         # &"body" | &"tech" | &"fight" | &"shelter"
@export var start_items: Array[StringName] = []
@export var practice_bonus: Dictionary = {}   # {&"medicine": 15.0, &"craft": 5.0}
@export var contact_tag: StringName    # &"quarantine" | &"artel" | &"commandant" | &"vagrants"
@export var duty: DutyResource         # что требует фракция и как часто (журнал/заказ/наряд/доля)
@export var start_reputation: Dictionary = {} # {&"soviet": 20.0, &"cleaners": -10.0}

class_name SpecializationDef extends Resource
@export var id: StringName            # &"surgeon" | &"energist" | &"sentry" | &"fortifier" | ...
@export var pillar: StringName         # &"body" | &"tech" | &"fight" | &"shelter"
@export var req: Dictionary = {}       # {&"medicine": 3, &"craft": 1}  — ранг, не очки практики
@export var techniques: Array[StringName] = []   # 3 приёма, минимум 2 обязательны
@export var apex: StringName           # вершинный приём; доступ = ранг + (чертёж | обучение у наставника)
@export var mentor_tag: StringName     # наставник фракции; репутация +50 даёт обучение, ниже -10 закрывает apex

# Перевод должности: OriginTransfer.apply(squad, new_origin) -> снимает старый duty,
# «забывает» родной приём, снимает 20 практики с основного навыка, ставит cooldown 30 суток.
# CharacterRuntime (Node): рантайм не пачкает Resource-ассеты.
# PracticeTracker начисляет практику за осмысленные действия и применяет decay раз в сутки.
# Приёмы проверяют rank + tool + state + blueprint; специализация добавляет к проверке только тег и apex.
# Никаких if has_perk в логике движения.
